  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576};
  static int passed;
  static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
  static Dictionary<string,object> D(object o){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(o));}
  static Dictionary<string,object>[] Rows(Dictionary<string,object> r,string key){return ((IEnumerable)r[key]).Cast<Dictionary<string,object>>().ToArray();}
  static object Invoke(string method,params object[] args){var t=typeof(Engine).Assembly.GetType("PZ3D.GameDiagnostics");if(t==null)throw new Exception("FAIL: evidence-based native diagnostics exists");try{return t.GetMethod(method,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
  static Dictionary<string,object> Analyze(string s){return D(Invoke("Analyze",s,DateTime.UtcNow));}
  sealed class Fixture {
   public readonly string Root;public readonly Engine E;
   public Fixture(){Root=Path.Combine(LauncherTestPaths.Root,"diagnostics-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"game"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true,()=>{throw new Exception("Steam probe forbidden");});Directory.CreateDirectory(E.Game);Directory.CreateDirectory(E.User);Directory.CreateDirectory(E.Data);}
   public string ConsolePath{get{return Path.Combine(E.User,"console.txt");}}
   public string Log(string name,string text){string p=Path.Combine(E.User,"logs",name);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,text,new UTF8Encoding(false));return p;}
   public Dictionary<string,object> Read(){return D(Invoke("Read",E));}
   public string[] Snapshot(){return Directory.GetFiles(Root,"*",SearchOption.AllDirectories).OrderBy(p=>p).Select(p=>p+"|"+File.GetLastWriteTimeUtc(p).Ticks+"|"+Convert.ToBase64String(File.ReadAllBytes(p))).Concat(Directory.GetDirectories(Root,"*",SearchOption.AllDirectories).OrderBy(p=>p)).ToArray();}
  }
  // Break caught: name/success/native-API noise is promoted into a culprit.
