  // Break caught: fresh mtime or invalid future timestamps makes historical evidence current.
  static void Age(){var f=new Fixture();File.WriteAllText(f.ConsolePath,DateTime.UtcNow.AddDays(-3).ToString("o")+" java.lang.OutOfMemoryError: Java heap space\n");File.SetLastWriteTimeUtc(f.ConsolePath,DateTime.UtcNow);Check((bool)Rows(f.Read(),"findings")[0]["historical"],"supporting old timestamp wins over fresh mtime");File.WriteAllText(f.ConsolePath,DateTime.UtcNow.ToString("o")+" java.lang.OutOfMemoryError: Java heap space\n");Check(!(bool)Rows(f.Read(),"findings")[0]["historical"],"recent age does not require a process/session probe");File.WriteAllText(f.ConsolePath,"LOG : General , 1> "+DateTime.Now.AddDays(-2).ToString("dd-MM-yyyy HH:mm:ss",CultureInfo.InvariantCulture)+" java.lang.OutOfMemoryError: Java heap space\n");Check((bool)Rows(f.Read(),"findings")[0]["historical"],"PZ explicit local timestamp is converted for age");Check((bool)Rows(Analyze("java.lang.OutOfMemoryError: Java heap space"),"findings")[0]["historical"],"unverifiable age is conservatively historical");Check(Rows(Analyze(DateTime.UtcNow.AddYears(1).ToString("o")+" java.lang.OutOfMemoryError: Java heap space"),"warnings").Any(),"impossible future evidence timestamp warns");var r=f.Read();Check(((string)r["reportText"]).Contains("当前游戏会话")&&((string)r["reportText"]).Contains("GPU"),"report states session and performance inference limits");}
