   File.WriteAllBytes(f.ConsolePath,new byte[]{239,187,191,255,255,0});r=f.Read();Check(Rows(r,"sources").Any(s=>(string)s["id"]=="console"&&(string)s["status"]=="rejected")&&!Rows(r,"findings").Any(s=>(string)s["source"]=="console"),"malformed BOM log is rejected without legacy fallback");
   File.WriteAllBytes(f.ConsolePath,new byte[]{0,0,0,0,1,2,3});Check(Rows(f.Read(),"warnings").Any(s=>(string)s["id"]=="source-encoding"),"binary text does not silently pass");
   File.WriteAllText(f.ConsolePath,"java.lang.OutOfMemoryError: Java heap space\n");using(var held=new FileStream(f.ConsolePath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){r=f.Read();Check(Rows(r,"warnings").Any(s=>(string)s["id"]=="source-unreadable"),"locked source warning instead of clean diagnosis");}
