   File.WriteAllText(f.ConsolePath,new string('x',300000)+"\njava.lang.OutOfMemoryError: Java heap space\n");r=f.Read();Check(Rows(r,"findings").Any(s=>(string)s["source"]=="console")&&Rows(r,"sources").Where(s=>(string)s["id"]=="console").All(s=>Convert.ToInt64(s["bytesRead"])<=262144&&(bool)s["truncated"]),"bounded tail retains recent errors");
   File.WriteAllText(Path.Combine(f.E.Game,"hs_err_pid123.log"),"# EXCEPTION_ACCESS_VIOLATION (0xc0000005)\n"+new string('x',300000)+"\n");Check(Rows(f.Read(),"findings").Any(s=>(string)s["id"]=="native-access-violation"),"bounded crash header survives tail retention");
   for(int i=0;i<140;i++)f.Log("bulk"+i+".log",new string('x',260000)+"\njava.lang.OutOfMemoryError: Java heap space\n");r=f.Read();Check(Rows(r,"sources").Length<=12&&Rows(r,"sources").Sum(s=>Convert.ToInt64(s["bytesRead"]))<=2097152,"file and aggregate byte collection bounded");Check(Rows(r,"warnings").Any(s=>(string)s["id"]=="collection-limit"),"discovery/file omission is surfaced");Check(Rows(r,"findings").Length<=24&&Rows(r,"warnings").Length<=16&&((string)r["reportText"]).Length<=48000,"public report output bounded");
  }
