  static void Reparse(){var f=new Fixture();string target=Path.Combine(f.Root,"foreign"),link=Path.Combine(f.E.User,"logs");Directory.CreateDirectory(target);Directory.CreateDirectory(link);File.WriteAllText(Path.Combine(target,"bad.log"),"java.lang.OutOfMemoryError: Java heap space\n");byte[] sub=Encoding.Unicode.GetBytes("\\??\\"+target),print=Encoding.Unicode.GetBytes(target);byte[] buffer=new byte[20+sub.Length+print.Length];Array.Copy(BitConverter.GetBytes(0xA0000003U),buffer,4);Array.Copy(BitConverter.GetBytes((ushort)(buffer.Length-8)),0,buffer,4,2);Array.Copy(BitConverter.GetBytes((ushort)sub.Length),0,buffer,10,2);Array.Copy(BitConverter.GetBytes((ushort)(sub.Length+2)),0,buffer,12,2);Array.Copy(BitConverter.GetBytes((ushort)print.Length),0,buffer,14,2);Array.Copy(sub,0,buffer,16,sub.Length);Array.Copy(print,0,buffer,18+sub.Length,print.Length);using(var h=CreateFile(link,0x40000000,3,IntPtr.Zero,3,0x02200000,IntPtr.Zero)){int returned;Check(!h.IsInvalid&&DeviceIoControl(h,0x000900A4,buffer,buffer.Length,IntPtr.Zero,0,out returned,IntPtr.Zero),"owned no-process junction fixture created");}var r=f.Read();Check(Rows(r,"warnings").Any(x=>(string)x["id"]=="source-reparse")&&Rows(r,"findings").Length==0,"reparse directory target is never collected");Check(File.ReadAllText(Path.Combine(target,"bad.log")).Contains("OutOfMemoryError"),"foreign target untouched");}
