  }
  public static int Main(){int failures=0;foreach(var run in new Action[]{Negatives,Rules,Age,Privacy,Collection,Reparse,Boundary,EdgeCases,AdditionalBounds,AccessDenied,PrefixedDuplicates,ContextualEvidence})try{run();}catch(Exception x){failures++;Console.WriteLine(x);}Console.WriteLine("Diagnostics assertions passed="+passed+", groups failed="+failures);return failures==0?0:1;}
